  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "When should you remodel your home?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The best time is when you're ready to make a significant change and can commit to planning six to twelve months in advance. Santa Barbara's mild year-round climate means there's no seasonal advantage—what matters is having your design finalized and permits in hand before construction begins."
      }
    },
    {
      "@type": "Question",
      "name": "How long does a whole home remodel take?",
      "acceptedAnswer": {
        "@type": "Answer",
